function binomCDF(k,n,p){if(k<0)return 0;if(k>=n)return 1;let lp=n*Math.log(1-p);let c=Math.exp(lp);for(let i=0;i<k;i++){lp+=Math.log((n-i)/(i+1))+Math.log(p/(1-p));c+=Math.exp(lp);}return Math.min(c,1);}
function binomTail(k,n,p){return 1-binomCDF(k-1,n,p);}
let n1=null,c1=null;
for(let n=1;n<=300;n++){for(let c=1;c<=n;c++){if(binomTail(c,n,0.1)<=0.05){n1=n;c1=c;break;}}if(n1!==null)break;}
let n2=null,c2=null;
for(let n=1;n<=300;n++){for(let c=0;c<=n;c++){if(binomCDF(c,n,0.1)>=0.90){n2=n;c2=c;break;}}if(n2!==null)break;}
function q2Cost(d1,d2,df,dd,p1,p2,pf,b1,b2,t1,t2,a,tf,s,l,d){const c1e=d1?(b1+t1)/(1-p1):b1;const c2e=d2?(b2+t2)/(1-p2):b2;const p1p=d1?0:p1;const p2p=d2?0:p2;const q=(1-p1p)*(1-p2p)*(1-pf);const base=c1e+c2e+a;if(df){if(dd)return(base+tf+(1-q)*d)/q;else return base+tf;}else{return(base+(1-q)*l)/q;}}
const P={p1:0.10,p2:0.10,pf:0.10,b1:4,b2:18,t1:2,t2:3,a:6,tf:3,s:56,l:6,d:5};
let bestProfit=-Infinity;
for(let d1=0;d1<=1;d1++)for(let d2=0;d2<=1;d2++)for(let df=0;df<=1;df++)for(let dd=0;dd<=1;dd++){const C=q2Cost(d1,d2,df,dd,P.p1,P.p2,P.pf,P.b1,P.b2,P.t1,P.t2,P.a,P.tf,P.s,P.l,P.d);const pr=P.s-C;if(pr>bestProfit)bestProfit=pr;}
const pp=0.10,bp=4,tp=2,ps=0.10,as=6,ts=3,ds=5,pf3=0.10,af=6,tf3=3,df3=5,s3=56,l3=6;
const partCost=(bp+tp)/(1-pp);
const semiCost=(3*partCost+as+ts)/(1-ps);
const q3c=(3*semiCost+af+tf3)/(1-pf3);
function betaSample(a,b){const m=a/(a+b);const sd=Math.sqrt(a*b/((a+b)*(a+b)*(a+b+1)));let x=m+sd*(Math.random()*2-1)*3;return Math.max(0.0001,Math.min(0.9999,x));}
const n4=2,k4=1;
let sum=0;const N=5000;
for(let i=0;i<N;i++){const p1=betaSample(k4+1,n4-k4+1);const p2=betaSample(k4+1,n4-k4+1);const pf=betaSample(k4+1,n4-k4+1);sum+=q2Cost(0,0,0,0,p1,p2,pf,P.b1,P.b2,P.t1,P.t2,P.a,P.tf,P.s,P.l,P.d);}
const q4c=sum/N;
const out={n1:n1,c1:c1,n2:n2,c2:c2,q2_profit:bestProfit,q3_cost:q3c,q4_cost:q4c};
fs.writeFileSync('results.json',JSON.stringify(out));
const config={discretization:{},physical:{"S-P0":0.1,"S-P1":0.10,"S-P2":0.10,"S-PF":0.10,"S-B1":4,"S-B2":18,"S-T1":2,"S-T2":3,"S-A":6,"S-TF":3,"S-S":56,"S-L":6,"S-D":5,"S-PV":0.10,"S-AV":6,"S-TV":3,"S-DV":5,"S-N4":2,"S-K":1},choices:{},property_set:null};
